'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { createStore } = require('../src/store');
const { createTicket, assignTicket, resolveTicket } = require('../src/tickets');
const portal = require('../src/portal');
const { weeklyRatingSummary, writeRatingSummary } = require('../src/jobs/rating-summary');

const DAY = 24 * 60 * 60 * 1000;
const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);
const acme = { id: 7, orgId: 1 };

function ratedTicket(store, score, ratedAtDays) {
  const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'x', body: 'x', now: at(0) });
  assignTicket(store, t.id, 41);
  resolveTicket(store, t.id, 41, { now: at(0) });
  portal.rateTicket(store, acme, t.id, score, { now: at(ratedAtDays) });
  return t;
}

test('an agent with ratings 5, 4 and 1 in the past seven days shows three ratings and an average of 3.33', () => {
  const store = createStore();
  ratedTicket(store, 5, 10);
  ratedTicket(store, 4, 12);
  ratedTicket(store, 1, 13);
  assert.deepEqual(weeklyRatingSummary(store, { now: at(14) }), [{ owner_id: 41, ratings: 3, average: 3.33 }]);
});

test('a rating exactly seven days old, or eight days old, is not counted', () => {
  const store = createStore();
  ratedTicket(store, 5, 0);
  assert.deepEqual(weeklyRatingSummary(store, { now: at(7) }), []);
  assert.deepEqual(weeklyRatingSummary(store, { now: at(8) }), []);
});

test('a rating with no owner is dropped from the summary instead of crashing', () => {
  const store = createStore();
  const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'x', body: 'x', now: at(0) });
  resolveTicket(store, t.id, 41, { now: at(0) });
  portal.rateTicket(store, acme, t.id, 5, { now: at(1) });
  assert.deepEqual(weeklyRatingSummary(store, { now: at(2) }), []);
});

test('the summary is written to exports/rating-summary.json', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'helpdesk-rating-summary-'));
  try {
    const store = createStore();
    ratedTicket(store, 5, 0);
    const out = writeRatingSummary(store, { dir, now: at(1) });
    assert.equal(out.rows, 1);
    const rows = JSON.parse(fs.readFileSync(out.file, 'utf8'));
    assert.deepEqual(rows, [{ owner_id: 41, ratings: 1, average: 5 }]);
