### Step 3 — write the minimal code

Create `src/jobs/rating-summary.js`:

```js
'use strict';
// Nightly. Writes exports/rating-summary.json: per agent, how many ratings their tickets
// received in the past seven days and the average score. The aggregation is pure so it can be
// tested without touching disk; the fs write is a thin wrapper, matching export-tickets.js.
const fs = require('node:fs');
const path = require('node:path');
const { EXPORT_DIR } = require('./export-tickets');

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;

function weeklyRatingSummary(store, { now = new Date() } = {}) {
  const totals = new Map();
  for (const r of store.listRatings()) {
    if (!r.owner_id) continue;
    if (now.getTime() - new Date(r.rated_at).getTime() >= WINDOW_DAYS * DAY) continue;
    const t = totals.get(r.owner_id) || { owner_id: r.owner_id, ratings: 0, total: 0 };
    t.ratings += 1;
    t.total += r.score;
    totals.set(r.owner_id, t);
  }
  return [...totals.values()]
    .map((t) => ({ owner_id: t.owner_id, ratings: t.ratings, average: Math.round((t.total / t.ratings) * 100) / 100 }))
    .sort((a, b) => a.owner_id - b.owner_id);
}

function writeRatingSummary(store, { dir = EXPORT_DIR, now = new Date() } = {}) {
  const rows = weeklyRatingSummary(store, { now });
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, 'rating-summary.json');
  fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
  return { file, rows: rows.length };
}

module.exports = { weeklyRatingSummary, writeRatingSummary, WINDOW_DAYS };
```

### Step 4 — run and confirm green

```
npm test
```

Expected: all tests pass, including the 4 new ones.

### Step 5 — commit

```
git add src/jobs/rating-summary.js test/rating-summary.test.js
git commit -m "csat: add the nightly weekly rating summary job"
```

## Exit criteria

- `npm test` passes with 4 tests in `test/rating-summary.test.js`.
- `git diff --stat` touches only `src/jobs/rating-summary.js` (created) and
  `test/rating-summary.test.js` (created).
- The acceptance criterion's exact numbers (3 ratings, average 3.33; 8-day-old excluded) are
  asserted literally, not approximately.

## Risks

- Floating-point averages: `Math.round(x * 100) / 100` is verified against the spec's own
  worked example (5, 4, 1 → 3.33) rather than trusted on inspection.
- Off-by-one on the 7-day boundary: covered by an explicit test at exactly `at(7)` and `at(8)`,
  not just "some day well past 7".

